'ob.texts_title' => 'Testi delle offerte',
'ob.texts_lede' => 'I blocchi di testo del documento d\'offerta — introduzione, oggetto, esclusioni, validità, prezzi e pagamento, termini, chiusura — per layout, lingua, filiale e cliente. Copiati in ogni nuova offerta, dove restano modificabili.',
'ob.texts_none' => 'Nessun modello — valgono i testi predefiniti. Aggiungerne uno con i pulsanti a destra.',
'ob.block' => 'Blocco',
'ob.texts_resolve' => 'Quale modello si applica: il più specifico attivo — cliente, poi filiale, poi lingua, poi layout; un modello legato ad altro cliente, filiale, lingua o layout non è mai usato. La lingua è quella degli account portale del cliente.',
'ob.text_name_ph' => 'es. Termini — filiale italiana',
'ob.any_layout' => '— qualsiasi layout —',
'ob.builtin_of' => 'Testo predefinito',
'ob.texts_order' => 'Ordine nel documento: Introduzione · Oggetto · Prezzi (tabella) · Esclusioni · Validità · Prezzi e pagamento · Termini · Chiusura. Un blocco vuoto non è stampato.',
'ob.d_intro' => "Spettabili Signori,\n\nvi ringraziamo per la richiesta. A seguito dei nostri contatti siamo lieti di sottoporvi la nostra offerta {no} per {vessel}, come dettagliato di seguito.",
'ob.d_scope' => 'L\'offerta comprende i servizi e le forniture elencati nella tabella prezzi. I lavori sono eseguiti da tecnici qualificati Golden A/S secondo le istruzioni dei costruttori, i requisiti di classe e bandiera applicabili e le Condizioni Generali di Servizio di Golden A/S.',
'ob.d_scope_system' => 'L\'offerta comprende l\'ingegneria, la fornitura, la supervisione dell\'installazione, la messa in servizio e la documentazione del sistema descritto nella tabella prezzi, secondo le istruzioni dei costruttori, i requisiti di classe e bandiera applicabili e le Condizioni Generali di Servizio di Golden A/S.',
'ob.d_scope_remote' => 'L\'offerta comprende i servizi, le apparecchiature e i piani di supporto remoto elencati nella tabella prezzi nell\'ambito del programma Remote Support & AR — OceanOpulence™, secondo le Condizioni Generali di Servizio di Golden A/S.',
'ob.d_exclusions' => 'Salvo indicazione nella tabella prezzi, non sono compresi: ricambi e materiali; viaggi, alloggio e diarie (addebitati secondo le tariffe di servizio Golden A/S); diritti di classe, bandiera e porto; lavoro fuori dal normale orario; ritardi non imputabili a Golden A/S.',
'ob.d_validity' => 'La presente offerta è valida per {validity_days} giorni, fino al {valid_until}.',
'ob.d_payment' => 'I prezzi sono in {currency}, IVA esclusa ove applicabile. I servizi orari sono fatturati sulle ore effettive secondo le tariffe allegate, con gli addebiti minimi della tariffa; i prezzi fissi come indicato. Pagamento con bonifico bancario o carta di credito secondo le nostre Condizioni Generali di Servizio.',
'ob.d_terms' => 'Le tariffe straordinarie giornaliere e orarie si applicano il sabato, la domenica, i festivi e oltre otto (8) ore dal lunedì al venerdì in Grecia o dieci (10) ore all\'estero e nelle isole greche. Tempo di viaggio, diaria fissa, chilometraggio e spese di viaggio secondo le tariffe di servizio Golden A/S {rate_list}. Nelle zone di riparazione designate in Grecia si applica una tassa pubblica di 180,00 € per il permesso di lavoro.',
'ob.d_closing' => "Confidiamo che quanto sopra risponda alle vostre esigenze e restiamo a disposizione per ogni chiarimento.\n\nCordiali saluti,\n{user}\n{branch}",
