'et.k_welcome' => 'Benvenuto — primo accesso (account del portale)',
'et.d_s_welcome' => 'Il suo accesso al portale Golden A/S',
'et.d_b_welcome' => "Gentile {name},\n\nil suo account sul portale Golden A/S è pronto. La preghiamo di seguire questi tre passi.\n\n1. PRIMO ACCESSO\n   Apra {url} ed effettui l'accesso con la sua e-mail {email} e la password provvisoria che le comunichiamo separatamente (per telefono o con un secondo messaggio — mai in questa e-mail).\n\n2. CAMBIO DELLA PASSWORD\n   Dopo il primo accesso clicchi sul suo avatar in alto a destra (Il mio account) e imposti una password personale sotto Nuova password: almeno 10 caratteri, non usata altrove.\n\n3. ATTIVAZIONE DELL'AUTENTICAZIONE A DUE FATTORI (2FA)\n   In Il mio account › Autenticazione a due fattori scansioni il codice QR con un'app authenticator (Microsoft Authenticator, Google Authenticator, Authy, …) e inserisca il codice a 6 cifre per confermare. Da quel momento ogni accesso richiede anche il codice dell'app.\n\nCinque password errate bloccano l'account per 15 minuti; se non riesce ad accedere, risponda a questa e-mail e lo sbloccheremo o reimposteremo la password.\n\n{signature}",
