/* ---- R47-002 ---- */
'eng.settings' => 'Sezioni di fase',
'eng.settings_lede' => 'Le sezioni della linea di processo con budget in ore — Engineering (Elettrico, Automazione, Meccanico, UI/UX, IT), Produzione, Cantiere e installazione, HAT / SAT, Commissioning — e le discipline che le alimentano. Il budget di una sezione è dato dalle ore a budget delle sue discipline nel Budget e consuntivo del sottoprogetto; le sue ore effettive sono le ore delle stesse discipline registrate su quella fase. Un\'unica fonte — concordata con il cliente; le ore extra approvate sono mostrate sopra di essa, mai sommate ad essa.',
'eng.map_title' => 'Matrice disciplina × sezione',
'eng.map_hint' => 'Spuntare le sezioni che ogni disciplina alimenta. Le discipline di engineering alimentano una sezione di engineering; un installatore alimenta Cantiere e installazione e HAT / SAT; un tecnico di service o di automazione HAT / SAT e Commissioning. Una disciplina che alimenta più sezioni ottiene una cella di budget per sezione in Budget e consuntivo, e la fase scelta sulla riga del foglio ore decide dove contano le sue ore. Le discipline di direzione e vendite restano non mappate.',
'eng.map_none' => '— non engineering',
'eng.map_save_hint' => 'Si applica immediatamente a ogni sotto-progetto (budget, consuntivi e la fase Engineering vengono ricalcolati dalla mappatura).',
